#include <linux/usb.h>
#include <sound/core.h>

int register_usb_audio_device(struct usb_interface *intf, const struct usb_device_id *usb_id) {
    struct usb_device *dev = interface_to_usbdev(intf);
    struct snd_card *card = NULL;
    int err = 0;

    if (!dev) {
        return -ENODEV;
    }

    if (dev->quirks & USB_QUIRK_AUDIO_BOOT_QUIRK) {
        err = apply_boot_quirk(dev);
        if (err < 0) {
            return err;
        }
    }

    if (is_device_registered(dev)) {
        return 0;
    }

    err = snd_card_new(&dev->dev, sizeof(struct snd_usb_audio), &card);
    if (err < 0) {
        return err;
    }

    if (dev->actconfig->interface[0].altsetting[0].bInterfaceClass == USB_CLASS_AUDIO &&
        dev->actconfig->interface[1].altsetting[0].bInterfaceClass == USB_CLASS_AUDIO) {
        handle_multi_control_interfaces(dev, card);
    }

    err = snd_card_register(card);
    if (err < 0) {
        snd_card_free(card);
        return err;
    }

    return 0;
}
